/* @layer shared-asset-extraction @kind logic */
import { hex } from '../c-hex';

const E3_BASE = (0xe3 - 0xc0) << 16;
const STRIDE = 0x78;
const N_REC = 0x20;

const sext = (b: number): number => (b >= 0x80 ? b - 256 : b);

/** tools/gen/animeng_gato.py w_e3: the E3 assembly records as src/data/animeng_e3_gato.h. */
const writeE3 = (rom: Uint8Array): string => {
  const o: string[] = [
    '// GENERATED by tools/gen/animeng_gato.py -- do not edit.',
    '// GATO E3 sprite-ASSEMBLY records (bank E3, base $E30000, stride 0x78), stage-1 indices 0x00-0x0B.',
    '// Layout per battle_anim_engine.md ADDENDUM 1 (contradiction C1 RESOLVED): each 0x78 record is',
    '//   [+0x00 .. +0x60] 48 x 16-bit CELL-WORDS (srcTile[0:10] | Hflip[bit14]; word 0 = blank) -> tile GATHER',
    '//   [+0x60 .. +0x78] 12 signed (dx,dy) pairs -> OAM cell POSITIONS (tile order 0x68 6A 6C 6E 80 82 84 86 88 8A 8C 8E)',
    '// The cell-word RASTER order maps 1:1 to VRAM 8x8 tiles 0x68-0x6F,0x78-0x7F,0x80-0x87,0x90-0x97,0x88-0x8F,0x98-0x9F.',
    '#ifndef CT_ANIMENG_E3_GATO_H',
    '#define CT_ANIMENG_E3_GATO_H',
    '#include <stdint.h>',
    '',
    'typedef struct { int8_t dx, dy; } CtAnimengPos;              // OAM cell offset from the live foot',
    'typedef struct { CtAnimengPos pos[12]; uint16_t cw[48]; } CtAnimengE3Rec;',
    `#define CT_ANIMENG_E3_GATO_N 0x${hex(N_REC, 2)}`,
    'static const CtAnimengE3Rec ctAnimengE3Gato[CT_ANIMENG_E3_GATO_N] = {',
  ];
  for (let n = 0; n < N_REC; n += 1) {
    const base = E3_BASE + n * STRIDE;
    const r = rom.subarray(base, base + STRIDE);
    const pos: string[] = [];
    for (let i = 0; i < 12; i += 1) {
      pos.push(`{${sext(r[0x60 + 2 * i] as number)},${sext(r[0x60 + 2 * i + 1] as number)}},`);
    }
    const cws: string[] = [];
    for (let i = 0; i < 48; i += 1) {
      cws.push(`0x${hex((r[2 * i] as number) | ((r[2 * i + 1] as number) << 8), 4)},`);
    }
    o.push(`  { // idx 0x${hex(n, 2)}`, `    { ${pos.join(' ')} },`);
    for (let i = 0; i < 48; i += 12) o.push(`    ${cws.slice(i, i + 12).join(' ')}${i === 0 ? '  // cw' : ''}`);
    o.push('  },');
  }
  o.push('};', '#endif', '');
  return o.join('\n');
};

export { writeE3 };
